const items = $input.all();
const now = new Date();
const in15min = new Date(now.getTime() + 15 * 60 * 1000);
const in20min = new Date(now.getTime() + 20 * 60 * 1000);

const upcoming = items.filter(i => {
  const start = new Date(i.json.start?.dateTime || i.json.start?.date || '');
  return start >= in15min && start <= in20min;
});

if (upcoming.length === 0) {
  return [{ json: { hasMeeting: false } }];
}

return upcoming.map(i => {
  const event = i.json;
  const start = new Date(event.start?.dateTime || event.start?.date);
  const meetLink = event.hangoutLink || event.conferenceData?.entryPoints?.[0]?.uri || '';
  const location = event.location || '';

  return {
    json: {
      hasMeeting: true,
      title: event.summary || 'Untitled Meeting',
      startTime: start.toTimeString().split(' ')[0].substring(0, 5),
      endTime: event.end?.dateTime ? new Date(event.end.dateTime).toTimeString().split(' ')[0].substring(0, 5) : '',
      meetLink,
      location,
      description: (event.description || '').substring(0, 200),
      organizer: event.organizer?.email || '',
      minutesUntil: Math.round((start - now) / 60000),
      timestamp: now.toISOString()
    }
  };
});
